import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Check for strong associations with outcome
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'cohort':
            # For clinical/cohort variables, check correlation with outcome
            corr = np.corrcoef(feats.x[:, i], feats.y)[0, 1]
            effects.append((fid, abs(corr)))
        else:
            # For other features, use t-test effect size
            y0 = feats.x[feats.y == 0, i]
            y1 = feats.x[feats.y == 1, i]
            if len(y0) > 0 and len(y1) > 0:
                t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
                effects.append((fid, abs(t_stat)))

    # Sort by effect size
    effects.sort(key=lambda x: x[1], reverse=True)

    # If no strong associations found, return empty design
    if not effects or effects[0][1] < 2.0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features (limit to 3 to keep model small)
    top_features = [f[0] for f in effects[:3]]

    # Check for correlated pairs among top features
    correlations = []
    for i, f1 in enumerate(top_features):
        for j, f2 in enumerate(top_features[i+1:], i+1):
            idx1 = feats.column(f1)
            idx2 = feats.column(f2)
            if idx1 >= 0 and idx2 >= 0:
                corr = np.corrcoef(feats.x[:, idx1], feats.x[:, idx2])[0, 1]
                if abs(corr) >= 0.6:
                    correlations.append((f1, f2, corr))

    # If we have strong correlations, form products
    products = []

    # Add all top features
    columns = list(top_features)

    # Add products for highly correlated pairs (only strong ones)
    for f1, f2, corr in correlations:
        if abs(corr) >= 0.8:
            products.append((f1, f2))

    # Remove near-duplicates (correlated features)
    unique_columns = list(set(columns))
    if len(unique_columns) < len(columns):
        columns = unique_columns

    # Check if any clinical feature is driving the outcome
    clinical_drivers = [fid for fid in top_features 
                       if feats.types[feats.column(fid)] in ['clinical', 'cohort']]

    if clinical_drivers:
        # Use clinical variable as driver if it's strongly associated
        drivers = tuple(clinical_drivers[:MAX_DRIVERS])
    else:
        drivers = ()

    # Create weighted score using top features
    loadings = {}
    for fid in columns:  # All selected columns for loading
        idx = feats.column(fid)
        if idx >= 0:
            # Weight by effect size
            y0 = feats.x[feats.y == 0, idx]
            y1 = feats.x[feats.y == 1, idx]
            if len(y0) > 0 and len(y1) > 0:
                t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
                loadings[fid] = abs(t_stat)

    # Normalize loadings
    if loadings:
        total = sum(loadings.values())
        if total > 0:
            for k in loadings:
                loadings[k] /= total

    return Design(drivers=drivers, columns=tuple(columns), products=tuple(products), loadings=loadings)

